-- Generated by scripts/build_compiled.py from src/fraudrules/rules/account-takeover/at-003-contact-change-then-payee.yaml. Do not edit.
-- AT-003 Email, phone or address change followed by a payee change
SELECT DISTINCT 'AT-003' AS rule_id, 'events' AS anchor_table, s1.id AS anchor_id
FROM events AS s1
JOIN events AS s0 ON s0.customer_id = s1.customer_id AND s0.ts < s1.ts AND s0.ts > s1.ts - 172800 AND (s0.event_type IN ('email_change', 'phone_change', 'address_change') AND s0.outcome = 'success')
WHERE (s1.event_type IN ('payee_added', 'payee_changed') AND s1.outcome = 'success');
